function resolveVertex(model,ref,boundary=false){let i=-1;if(typeof ref==='number')i=ref;else if(typeof ref==='string')i=model.vertexIds.indexOf(ref);else if(validUV(ref))i=nearestVertex(model,ref,{boundary});else if(ref&&typeof ref==='object'){if(ref.vertexId!=null)i=typeof ref.vertexId==='number'?ref.vertexId:model.vertexIds.indexOf(ref.vertexId);else if(Number.isInteger(ref.index))i=ref.index;else if(validUV(ref.uv))i=nearestVertex(model,ref.uv,{boundary});}if(!Number.isInteger(i)||i<0||i>=model.active.length||!model.active[i]||boundary&&!model.boundary.has(i))throw new Error('操作引用的顶点或边界在当前组织中不可用');return i;}
